<main class="page-content"><div class="page-header"><div><p class="eyebrow">Agenda</p><h1>Clases particulares reservadas</h1></div></div><?php if(!empty($error)): ?><div class="alert alert-error"><?=e($error)?></div><?php endif; ?><div class="card" style="padding:1rem"><table><thead><tr><th>Fecha</th><th>Horario</th><th>Monitor</th><th>Deportista</th><th>Apoderado</th><th>Estado</th><th>Ingreso base</th></tr></thead><tbody><?php foreach($reservas as $r): ?><tr><td><?=e(date('d/m/Y',strtotime($r['fecha'])))?></td><td><?=e(substr($r['inicio'],11,5))?> - <?=e(substr($r['fin'],11,5))?></td><td><?=e($r['monitor'])?></td><td><?=e($r['deportista'])?></td><td><?=e($r['cliente'])?></td><td><?=e($r['estado'])?></td><td>$<?=number_format((float)$r['base_amount'],0,',','.')?></td></tr><?php endforeach; ?></tbody></table><?php if(empty($reservas)): ?><p class="empty">No hay clases reservadas próximas.</p><?php endif; ?></div></main>